contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // send ether to this test contract so it can forward to c in the test
    receive() external payable {}

    // single public function with all test logic
    // params:
    //   depositorAmount - amount this test will send into c via fallback (must be <= this.balance)
    //   recipient - address to receive withdrawn funds
    //   caller - address that will call withdrawAll (simulated by testing msg.sender via tx origin is not allowed; instead we pass caller as a parameter and require it equals c.owner() when we want owner)
    // We cannot change msg.sender in Solidity; instead we observe behavior through balances and owner getter.
    // To distinguish P vs M: after funding c, if a non-owner could withdraw all, then c's balance becomes 0 despite caller not being owner.
    function check(uint256 depositorAmount, address payable recipient, address caller) public payable {
        // Preconditions for the test
        require(address(this).balance >= depositorAmount, "not enough ETH in test contract");
        // fund contract c by forwarding Ether to it using fallback
        // send depositorAmount to c
        (bool sent, ) = address(c).call{value: depositorAmount}("");
        require(sent, "fund failed");

        // record balances before withdraw attempt
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        // require we actually funded it
        require(beforeC == depositorAmount, "unexpected funding");

        // calling withdrawAll as some caller: we cannot change msg.sender in solidity, but we can express the property
        // by checking owner and then invoking withdrawAll from this contract (which will be msg.sender here).
        // If caller == address(this) then this call models owner calling when owner==this. Otherwise it models a non-owner call.
        // So we require that owner != address(this) when modelling non-owner; if caller equals address(this) we model owner.

        // Ensure caller parameter matches whether this contract is owner or not
        if (caller == address(this)) {
            // we intend to model the owner calling: ensure c.owner()==address(this)
            // If not, make the test inapplicable
            require(c.owner() == address(this), "caller marked owner but not owner");
        } else {
            // we intend to model a non-owner calling: ensure c.owner() != address(this)
            require(c.owner() != address(this), "caller marked non-owner but this contract is owner");
        }

        // perform the withdrawAll call from this contract (msg.sender == address(this))
        c.withdrawAll(recipient);

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // The distinguishing rule: if the caller is not the owner (i.e., this contract is not owner), then withdrawAll must NOT transfer the contract's balance out.
        // This holds on original P (non-owner cannot withdraw) and is violated by M (anyone can withdraw).
        if (caller != address(this)) {
            assert(afterC == beforeC && afterRecipient == beforeRecipient);
        } else {
            // If caller is owner, then withdraw should have moved the full balance to recipient
            assert(afterC == 0 && afterRecipient == beforeRecipient + beforeC);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address payable recipient) public payable {
        // No precondition needed: we test general caller behavior.
        bool reverted;
        // Make the call from this contract (simulating arbitrary caller via parameter `caller` isn't possible),
        // but we can express the rule in terms of whether this caller equals c.owner() by calling c.owner().
        // Call withdrawAll as this contract (this is the arbitrary caller under test).
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The general rule: if this contract's address is equal to c.owner(), the call must not revert; otherwise it must revert.
        // We observe c.owner() via public getter and the revert flag.
        address owner = c.owner();
        assert((owner == address(this)) == (!reverted));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address payable recipient) public payable {
        require(caller != address(0));
        // simulate call by 'caller' by using low-level call to invoke withdrawAll on c
        // We cannot change msg.sender in Solidity directly; instead, we express the property
        // using the public owner getter and whether the call from this contract (not caller)
        // would revert. The distinguishing condition is: if this contract is not the owner,
        // calling withdrawAll should revert. So require this contract is not owner to make
        // the assertion meaningful for all inputs.
        require(address(this) != c.owner());

        // attempt to call withdrawAll as this contract (which is not owner)
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }

        // For the original contract P: since address(this) != owner, the call must revert.
        // For mutant M (owner check removed): the call would succeed. So assert that the call reverted.
        assert(reverted == true);
    }
    receive() external payable { }
}

