pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: caller address and recipient address and amount
    function testFuzz_property(address caller, address recipient, uint128 amount) public {
        // keep fuzzed domain wide but sensible: amount > 0 and not overflowing vm deal
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));
        // cap amount to a reasonable bound
        uint256 amt = bound(amount, 1, 1 ether);

        // fund the contract with amt from this test contract (owner)
        vm.deal(address(this), amt);
        // send funds into c so it has balance to withdraw
        payable(address(c)).transfer(amt);

        // First: owner (this) can call withdrawAll and drain contract: this should succeed
        // perform owner withdrawal to reset state for the subsequent non-owner attempt
        // use try/catch to observe success without reverting the test
        bool ownerOk;
        try c.withdrawAll(recipient) {
            ownerOk = true;
        } catch {
            ownerOk = false;
        }
        // Sanity: owner call must succeed for all inputs
        assertTrue(ownerOk);

        // Re-deposit funds so the contract has balance again for non-owner attempt
        vm.deal(address(this), amt);
        payable(address(c)).transfer(amt);

        // Now have arbitrary caller attempt to withdraw
        // If caller == owner (this), the behavior should still be allowed; only non-owners must be prevented
        bool callerOk;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            callerOk = true;
        } catch {
            callerOk = false;
        }

        // The universal property we assert: if the caller is NOT the owner, the withdraw call MUST NOT succeed.
        // This holds for the reference implementation for every input, but the mutant that removed the
        // require(msg.sender == owner) will allow some non-owner caller to succeed, causing this assertion to fail.
        if (caller != address(this)) {
            assertTrue(!callerOk);
        } else {
            // when caller is the owner, withdraw must succeed
            assertTrue(callerOk);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // supply Ether to this test contract so it can forward to c
    receive() external payable {}

    // single public function containing the test
    // params:
    // - sender: the address that will call withdrawAll (simulated via address(this) only; we use require to constrain sender equals owner or not)
    // - fundAmount: wei to send into c before withdrawal
    // - recipient: address to pass to withdrawAll
    function check(address ownerAddr, uint256 fundAmount, address payable recipient) public payable {
        // Precondition: this test contract must hold enough balance to fund c
        require(address(this).balance >= fundAmount);

        // Fund c by sending Ether to its fallback
        payable(address(c)).transfer(fundAmount);

        // Observe c balance before withdrawal
        uint256 before = address(c).balance;

        // We will attempt to withdraw from c by calling withdrawAll as this contract.
        // The distinguishing behavior depends on whether msg.sender equals c.owner().
        // Ensure ownerAddr matches c.owner() so the test covers the case where this caller is the owner.
        // For the original contract P, when msg.sender == owner the call should succeed and drain c;
        // for the mutant M (require inverted), the same call would revert and leave balance intact.
        // Enforce that ownerAddr is indeed c.owner().
        require(ownerAddr == c.owner());

        // Now perform the withdrawal: this contract acts as msg.sender and must be the ownerAddr
        // To simulate that, we require that ownerAddr equals address(this)
        // This keeps the test generic: caller is owner when address(this) == ownerAddr.
        // The verifier will consider both possibilities; we constrain to the owner case to distinguish P vs M.
        require(address(this) == ownerAddr);

        // Actual state-changing call on c: attempt to withdraw to recipient
        c.withdrawAll(recipient);

        // Observe c balance after withdrawal
        uint256 after = address(c).balance;

        // Assert the distinguishing property: after withdrawal, c's balance must be zero (i.e., owner can drain it)
        // This holds on the original contract P for owner callers, and is violated by the mutant M where owner is disallowed.
        assert(after == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // send ETH into this test contract so it can forward to c in the test
    receive() external payable {}

    // params: owner is the caller of withdrawAll, recipient is target, fund is amount to seed into c
    function run(address owner, address payable recipient, uint256 fund) public payable {
        // preconditions: this contract must have enough ETH to fund c
        require(address(this).balance >= fund, "insufficient funds to seed c");

        // seed contract c with ETH by sending directly to its fallback
        (bool sent,) = address(c).call{value: fund}("");
        require(sent, "seed failed");

        // record recipient balance before withdraw
        uint256 before = recipient.balance;

        // the owner must be msg.sender of withdrawAll; simulate by calling withdrawAll from owner
        // Since we cannot change msg.sender, require that owner == address(this) so this contract can call
        require(owner == address(this), "owner must be this contract to call withdrawAll");

        // call withdrawAll as the owner (this contract)
        c.withdrawAll(recipient);

        // recipient should have increased by the full prior contract balance (fund)
        uint256 after = recipient.balance;
        assert(after - before == fund);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address payable recipient) public payable {
        require(caller != address(0) && recipient != address(0));
        // Ensure this contract can act as caller by forwarding via delegatecall-like pattern is impossible here.
        // Instead, we rely on the public owner getter to set precondition: only run when caller equals c.owner()
        address owner = c.owner();
        require(caller == owner);

        // Call withdrawAll as the owner: we simulate by requiring msg.sender==owner in C, so we must be the owner.
        // To actually send the call as owner, tests typically deploy C with this test as owner. The property is about revert behavior.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: when caller is owner, withdrawAll reverts exactly when the contract balance is zero.
        assert(reverted == (address(c).balance == 0));
    }
    receive() external payable {}
}

